//! Photo backup — camera-roll intake and the debounced backup tick.
use super::*;

impl Worker {
    /// One-shot photo backup: uploads the given images into a "Photos"
    /// folder at the drive root, creating it when missing. Renditions are
    /// generated by the normal upload path.
    pub(super) async fn backup_photos(&mut self, paths: Vec<PathBuf>) -> Result<()> {
        let images: Vec<PathBuf> = paths
            .into_iter()
            .filter(|p| {
                p.file_name()
                    .and_then(|n| n.to_str())
                    .map(is_image_name)
                    .unwrap_or(false)
            })
            .collect();
        if images.is_empty() {
            return Err(anyhow!("no image files selected"));
        }
        // Reuse the existing "Photos" folder or create it.
        let folder_id = self
            .namespace
            .folders
            .values()
            .find(|d| d.parent.is_empty() && d.name == "Photos" && !d.tombstoned)
            .map(|d| d.id.clone());
        let folder_id = match folder_id {
            Some(id) => id,
            None => {
                let op = ops::mkdir("", "Photos");
                let id = op.obj.clone();
                self.send_and_project(&op).await?;
                id
            }
        };
        for path in images {
            let key = path.to_string_lossy().to_string();
            if self.journal.backup_seen.contains(&key) {
                continue;
            }
            if let Err(e) = self.upload(path.clone(), folder_id.clone()).await {
                self.emit(Event::Error {
                    context: "photo backup",
                    message: format!("{}: {e:#}", path.display()),
                });
            } else {
                self.journal.backup_seen.insert(key);
                self.save_journal();
            }
        }
        Ok(())
    }

    /// Poll the watched backup folder for new images (ledger-driven, like
    /// TDrive's backup lifecycle — uploaded paths are never re-sent).
    pub(super) async fn backup_tick(&mut self) -> Result<()> {
        let Some(dir) = self.journal.backup_dir.clone() else {
            return Ok(());
        };
        let paths: Vec<PathBuf> = std::fs::read_dir(&dir)
            .map(|rd| rd.flatten().map(|e| e.path()).collect::<Vec<_>>())
            .unwrap_or_default()
            .into_iter()
            .filter(|p| {
                !self
                    .journal
                    .backup_seen
                    .contains(&p.to_string_lossy().to_string())
            })
            .collect();
        // An empty or fully-uploaded watch dir is the steady state, not
        // an error — don't spam the status bar every tick.
        if paths.is_empty() {
            return Ok(());
        }
        self.backup_photos(paths).await
    }
}
